use base64::Engine as _;
use tauri::{AppHandle, Manager};

/// One-way PowerPoint export helper: writes generated bytes to the
/// user's Downloads folder and returns the final path, so the frontend
/// can open it with the default app (PowerPoint) via plugin-opener.
///
/// Filenames arrive pre-slugged from the frontend (`my-sermon.pptx`);
/// path separators are rejected defensively, and collisions get
/// `name (2).pptx` suffixes — the returned path is always the file
/// that was actually written.
#[tauri::command]
pub fn save_export(
    app: AppHandle,
    file_name: String,
    base64_data: String,
) -> Result<String, String> {
    if file_name.is_empty()
        || file_name.contains('/')
        || file_name.contains('\\')
        || file_name.contains("..")
    {
        return Err("Refused unsafe export filename.".into());
    }
    let dir = app
        .path()
        .download_dir()
        .map_err(|e| format!("No download folder: {e}"))?;
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(base64_data.as_bytes())
        .map_err(|e| format!("Bad export payload: {e}"))?;

    let (stem, ext) = match file_name.rsplit_once('.') {
        Some((stem, ext)) => (stem.to_string(), format!(".{ext}")),
        None => (file_name.clone(), String::new()),
    };
    let mut candidate = dir.join(format!("{stem}{ext}"));
    let mut counter = 2;
    while candidate.exists() {
        candidate = dir.join(format!("{stem} ({counter}){ext}"));
        counter += 1;
    }
    std::fs::write(&candidate, bytes)
        .map_err(|e| format!("Could not write export: {e}"))?;
    candidate
        .to_str()
        .map(str::to_string)
        .ok_or_else(|| "Export path is not valid unicode.".to_string())
}

/// Transient PowerPoint handoff: writes generated bytes to a fixed path in
/// the OS temp dir (overwritten on every export) and returns it, so the
/// frontend can open it via plugin-opener. Nothing lands in Downloads and
/// there is nothing to delete after presenting — the next export reuses
/// the same file. Our staged deck is closed first (see below), so an
/// update reopens in one window; when the file is still locked, a
/// suffixed sibling is used so the update still opens.
#[tauri::command]
pub fn save_transient_export(base64_data: String) -> Result<String, String> {
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(base64_data.as_bytes())
        .map_err(|e| format!("Bad export payload: {e}"))?;
    // Close our staged deck in the running PowerPoint (if any) so the
    // rewrite below reuses the same file instead of opening a second
    // copy. Other presentations are left alone.
    close_staged_presentations();
    let dir = std::env::temp_dir().join("kjv-bible");
    std::fs::create_dir_all(&dir).map_err(|e| format!("Could not stage export: {e}"))?;
    let target = dir.join("kjv-sermon-deck.pptx");
    if std::fs::write(&target, &bytes).is_ok() {
        // Best-effort: drop stale locked-siblings now the main file won.
        if let Ok(entries) = std::fs::read_dir(&dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path != target {
                    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                        if name.starts_with("kjv-sermon-deck (") && name.ends_with(".pptx") {
                            let _ = std::fs::remove_file(&path);
                        }
                    }
                }
            }
        }
        return path_string(&target);
    }
    // Locked or otherwise busy: suffixed sibling, newest wins.
    let mut counter = 2;
    loop {
        let alt = dir.join(format!("kjv-sermon-deck ({counter}).pptx"));
        if std::fs::write(&alt, &bytes).is_ok() {
            return path_string(&alt);
        }
        counter += 1;
        if counter > 50 {
            return Err("Could not stage export: target is locked.".into());
        }
    }
}

fn path_string(path: &std::path::Path) -> Result<String, String> {
    path.to_str()
        .map(str::to_string)
        .ok_or_else(|| "Export path is not valid unicode.".to_string())
}

/// One verse pre-formatted by the frontend for a live append (all values
/// are final — the backend only places them).
#[derive(serde::Deserialize, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LiveVerse {
    pub label: String,
    pub text: String,
    pub body_pt: f32,
    pub fill_ole: i32,
    pub text_ole: i32,
    pub ref_ole: i32,
}

#[derive(serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LiveAppendInfo {
    pub added: usize,
    pub total: usize,
    pub resumed_at: usize,
}

/// Mid-show update: appends verses to the RUNNING slideshow of our staged
/// deck and restarts the show at the same slide (one brief flash, place
/// kept, new verses at the end). Returns `Ok(None)` when there is no live
/// show of our deck — the caller then uses the file flow instead.
/// PowerPoint snapshots a show at start, so a truly invisible append is
/// impossible; this is the closest achievable behavior.
#[tauri::command]
pub fn append_verses_live(additions: Vec<LiveVerse>) -> Result<Option<LiveAppendInfo>, String> {
    if additions.is_empty() {
        return Err("Nothing to append.".into());
    }
    #[cfg(not(windows))]
    {
        let _ = &additions;
        return Ok(None);
    }
    #[cfg(windows)]
    {
        append_verses_live_windows(additions)
    }
}

#[cfg(windows)]
fn append_verses_live_windows(
    additions: Vec<LiveVerse>,
) -> Result<Option<LiveAppendInfo>, String> {
    let dir = std::env::temp_dir().join("kjv-bible");
    std::fs::create_dir_all(&dir).map_err(|e| format!("Could not stage append: {e}"))?;
    let json_path = dir.join("live-append.json");
    std::fs::write(&json_path, serde_json::to_string(&additions).map_err(|e| e.to_string())?)
        .map_err(|e| format!("Could not stage append: {e}"))?;
    let path_literal = json_path
        .to_str()
        .ok_or_else(|| "Append path is not valid unicode.".to_string())?
        .replace('\'', "''");

    // Structural ops abort on error; cosmetic ones (vertical anchor) fall
    // back silently. `NONE` means no live show of our deck — not a failure.
    let script = format!(
        r#"
$ErrorActionPreference = 'Stop'
try {{ $pp = [Runtime.InteropServices.Marshal]::GetActiveObject('PowerPoint.Application') }} catch {{ Write-Output 'NONE'; exit 0 }}
$target = $null; $show = $null
foreach ($w in @($pp.SlideShowWindows)) {{
  try {{ $p = $w.Presentation; if ($p.FullName -like '*kjv-bible*') {{ $target = $p; $show = $w; break }} }} catch {{}}
}}
if ($null -eq $target) {{ Write-Output 'NONE'; exit 0 }}
$items = Get-Content -Raw -Path '{path_literal}' | ConvertFrom-Json
# Template: the hidden verse-styled slide exports append last (duplicating
# it copies background art, geometry, and fonts exactly). Without one
# (older file), fall back to the last slide.
$tpl = $null
foreach ($s in @($target.Slides)) {{ try {{ if ($s.SlideShowTransition.Hidden) {{ $tpl = $s; break }} }} catch {{}} }}
if ($null -eq $tpl) {{ $tpl = $target.Slides($target.Slides.Count) }}
foreach ($it in @($items)) {{
  $slide = $tpl.Duplicate().Item(1)
  $slide.MoveTo($target.Slides.Count)
  $slide.SlideShowTransition.Hidden = $false
  $t = @($slide.Shapes | Where-Object {{ $_.HasTextFrame }})
  if ($t.Count -ge 1) {{
    $b = $t[0]
    $b.Left = 57.6; $b.Top = 50.4; $b.Width = 844.56; $b.Height = 396
    $r = $b.TextFrame.TextRange
    $r.Text = $it.text
    $r.Font.Name = 'Georgia'
    $r.Font.Size = [float]$it.bodyPt
    $r.Font.Bold = 0; $r.Font.Italic = 0; $r.Font.Underline = 0
    $r.Font.Color.RGB = [int]$it.textOle
    $r.ParagraphFormat.Alignment = 2
  }}
  if ($t.Count -ge 2) {{
    $f = $t[1]
    $f.Left = 57.6; $f.Top = 464.4; $f.Width = 844.56; $f.Height = 39.6
    $q = $f.TextFrame.TextRange
    $q.Text = $it.label
    $q.Font.Name = 'Calibri'
    $q.Font.Size = 26
    $q.Font.Bold = 0; $q.Font.Italic = 0; $q.Font.Underline = 0
    $q.Font.Color.RGB = [int]$it.refOle
    $q.ParagraphFormat.Alignment = 2
  }}
  for ($i = 2; $i -lt $t.Count; $i++) {{ $t[$i].TextFrame.TextRange.Text = '' }}
}}
$target.Save()
$pos = $show.View.CurrentShowPosition
$total = $target.Slides.Count
$show.View.Exit()
$st = $target.SlideShowSettings
try {{ $st.RangeType = 3; $st.StartingSlide = $pos; $st.EndingSlide = $total }} catch {{}}
$w2 = $st.Run()
try {{ if ($w2.View.CurrentShowPosition -ne $pos) {{ $w2.View.GotoSlide($pos) }} }} catch {{}}
try {{ $st.RangeType = 1 }} catch {{}}
@{{ added = @($items).Count; total = $total; resumedAt = $pos }} | ConvertTo-Json -Compress
"#
    );
    let out = std::process::Command::new("powershell")
        .args(["-NoProfile", "-NonInteractive", "-Command", &script])
        .output()
        .map_err(|e| format!("Live append failed: {e}"))?;
    let _ = std::fs::remove_file(&json_path);
    if !out.status.success() {
        return Err(format!(
            "Live append failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    let line = String::from_utf8_lossy(&out.stdout)
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .last()
        .unwrap_or("")
        .to_string();
    if line == "NONE" {
        return Ok(None);
    }
    serde_json::from_str::<LiveAppendInfo>(&line)
        .map(Some)
        .map_err(|_| format!("Live append failed: unexpected output: {line}"))
}

/// Best-effort: close any presentation staged by this app (`kjv-bible`
/// temp files) in the running PowerPoint, so the next export reopens one
/// file in one window. Other presentations are untouched, and PowerPoint
/// itself quits only when nothing else is open. Windows-only (PowerPoint
/// COM); every failure is ignored — unwritten-not-running just means
/// there is nothing to close, and the caller still falls back to a
/// suffixed sibling if the file stays locked.
fn close_staged_presentations() {
    #[cfg(windows)]
    {
        // One-way model: the app owns the content, so staged decks close
        // without saving (`Saved = $true` skips the save prompt — the
        // file is about to be overwritten anyway).
        let script = r#"
try {
  $pp = [Runtime.InteropServices.Marshal]::GetActiveObject('PowerPoint.Application')
  foreach ($p in @($pp.Presentations)) {
    try { if ($p.FullName -like '*kjv-bible*') { $p.Saved = $true; $p.Close() } } catch {}
  }
  if ($pp.Presentations.Count -eq 0) { $pp.Quit() }
} catch {}
"#;
        let _ = std::process::Command::new("powershell")
            .args(["-NoProfile", "-NonInteractive", "-Command", script])
            .output();
    }
}
